package models;

public class PlayerData {
    int score;
    int wicketsTaken;
    int numberOfSix;
    int numberOfFour;
    int numberOfBallsFaced;

    public PlayerData() {
        this.score = 0;
        this.wicketsTaken = 0;
        this.numberOfSix = 0;
        this.numberOfFour = 0;
        this.numberOfBallsFaced = 0;
    }

    public int getScore() {
        return score;
    }

    public int getWicketsTaken() {
        return wicketsTaken;
    }

    public int getNumberOfSix() {
        return numberOfSix;
    }

    public int getNumberOfFour() {
        return numberOfFour;
    }

    public int getNumberOfBallsFaced() {
        return numberOfBallsFaced;
    }

    private void updateScore(int score) {
        this.score += score;
    }

    private void updateNumberOfSix() {
        this.numberOfSix += 1;
    }

    private void updateNumberOfFour() {
        this.numberOfFour += 1;
    }

    private void updateNumberOfBallsFaced() {
        this.numberOfBallsFaced += 1;
    }

    public void updatePlayerScore(int score) {
        updateScore(score);
        updateNumberOfBallsFaced();
        switch (score) {
        case 4:
            updateNumberOfFour();
            break;
        case 6:
            updateNumberOfSix();
        }
    }

}

package models;

import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedList;
import java.util.List;

public class Team {

    List<CricketPlayer> players;
    Deque<CricketPlayer> availablePlayers;
    int totalTeamScore;
    int totalWickets;

    public int getTotalTeamScore() {
        return totalTeamScore;
    }

    CricketPlayer currentBatsman;
    CricketPlayer strikeBatsman;
    String teamName;

    public Team(String teamName) {
        this.players = new ArrayList<>();
        this.availablePlayers = new LinkedList<>();
        this.totalTeamScore = 0;
        this.currentBatsman = null;
        this.strikeBatsman = null;
        this.teamName = teamName;
        this.totalWickets = 0;
    }

    public void addPlayersToTeam(CricketPlayer player) {
        if (this.players.contains(player)) {
            System.out.println("Player Already in the team");
        } else {
            this.players.add(player);
            availablePlayers.addLast(player);
        }
    }

    public void initializePlayers() {
        if (availablePlayers.size() >= 2) {
            this.currentBatsman = availablePlayers.poll();
            this.strikeBatsman = availablePlayers.poll();
        }
    }

    public String getTeamName() {
        return teamName;
    }

    public List<CricketPlayer> getPlayers() {
        return new ArrayList<>(players);
    }

    public boolean isNextBatsmanAvailable() {
        if (availablePlayers.size() != 0) {
            return true;
        } else {
            return false;
        }
    }

    public Player wicketFallen() {
        CricketPlayer player = availablePlayers.poll();
        this.currentBatsman = player;
        return player;
    }

    public void swapStrike() {
        CricketPlayer temp = this.currentBatsman;
        this.currentBatsman = this.strikeBatsman;
        this.strikeBatsman = temp;
    }

    public boolean updateScore(int score) {
        currentBatsman.updatePlayerScore(score);
        updateStrikeBatsman(score);
        this.totalTeamScore += score;
        return true;
    }

    private void updateStrikeBatsman(int score) {
        if (score != 0 && score % 2 != 0) {
            swapStrike();
        }
    }

    public int getTotalWickets() {
        return totalWickets;
    }

    public boolean updateWicket() {
        this.totalWickets +=1;
        if (isNextBatsmanAvailable()) {
            updateScore(0);
            wicketFallen();
            return true;
        } else {
            System.out.println("no batsman to play");
            return false;
        }
    }
}

package UI;

import models.CricketPlayer;
import models.PlayerData;
import models.Team;

import java.util.UUID;

public class Dashboard {
    String id;
    private static final String PLAYER_NAME_COL = "Player Name";
    private static final String SCORE = "Score";
    private static final String NO_OF_4 = "4's";
    private static final String NO_OF_6 = "6's";
    private static final String BALLS = "Balls";

    public Dashboard() {
        this.id = UUID.randomUUID().toString();
    }

    public void displayScoreCard(Team currentTeam) {
        displayHeader(currentTeam);
        displayTeamStats(currentTeam);
        displayTeamFinalScore(currentTeam);
    }

    private void displayTeamFinalScore(Team currentTeam) {
        System.out.println("Total : " + currentTeam.getTotalTeamScore() + "/" + currentTeam.getTotalWickets());
    }

    private void displayTeamStats(Team currentTeam) {
        for (CricketPlayer player : currentTeam.getPlayers()) {
            PlayerData data = player.getPlayerData();
            System.out.println(
                player.getPlayerName() + "          | " + data.getScore() + " | " + data.getNumberOfFour() + " | "
                    + data
                    .getNumberOfSix() + " | " + data.getNumberOfBallsFaced());
        }
    }

    private void displayHeader(Team team) {
        System.out.println("Scorecard for Team  " + team.getTeamName());
        System.out.println(PLAYER_NAME_COL + " | " + SCORE + " | " + NO_OF_4 + " | " + NO_OF_6 + " | " + BALLS);
    }
}

