        return listOfServicePincode.contains(pinCode);
    }

    public boolean isEnoughQuantityAvailable() {
        return this.foodItem.getQuantity() > 0;
    }

    public Double getRestaurantRating() {
        return ratings.getAverageRating();
    }
}

