package com.company.cache.policies;

import com.company.algorithm.DoublyLinkedList;
import com.company.algorithm.DoublyLinkedListNode;

import java.util.HashMap;
import java.util.Map;

public class LRUEvictionPolicy<K> implements EvictionPolicy<K> {

	private final DoublyLinkedList<K> dll;
	private final Map<K, DoublyLinkedListNode<K>> nodeMap;

	public LRUEvictionPolicy() {
		this.nodeMap = new HashMap<>();
		this.dll = new DoublyLinkedList<>();
	}

	@Override
	public void keyAccessed(K key) {
		DoublyLinkedListNode<K> node;

		if (nodeMap.containsKey(key)) {
			node = nodeMap.get(key);
			dll.detachNode(node);
			dll.addNodeToLast(node);
		} else {
			node = dll.addElementToLast(key);
			nodeMap.put(key, node);
		}
	}

	@Override
	public K removeKey() {
		DoublyLinkedListNode<K> firstNode = dll.getFirstNode();
		if (firstNode == null) {
			return null;
		}
		dll.detachNode(firstNode);
		return firstNode.getElement();
	}
}

package com.company.cache.storage;

import com.company.cache.exception.NotFoundException;
import com.company.cache.exception.StorageFullException;

import java.util.HashMap;
import java.util.Map;

public class HashMapBasedStorage<K, V> implements Storage<K, V> {

	private final Integer capacity;
	private final Map<K, V> storage;

	public HashMapBasedStorage(Integer capacity) {
		this.capacity = capacity;
		this.storage = new HashMap<>();
	}

	@Override
	public void put(K key, V value) {
		if (isStorageFull()) throw new StorageFullException("Storage capacity is full.");
		this.storage.put(key, value);
	}

	@Override
	public void remove(K key) {
		if (!this.storage.containsKey(key)) throw new NotFoundException("No value cached with that key.");
		this.storage.remove(key);
	}

	@Override
	public V get(K key) {
		if (!this.storage.containsKey(key)) throw new NotFoundException("No value cached with that key.");
		return this.storage.get(key);
	}

	private boolean isStorageFull() {
		return this.storage.size() == capacity;
	}
}

