package io.abhi.cartdesign;

import java.util.List;

public class ApplicableOnAllItems extends Coupon {
  private double percent;

  public ApplicableOnAllItems(int id, String name, double percent) {
    super(id, name);
    this.percent = percent;
  }

  public double getPercent() {
    return percent;
  }

  public void setPercent(double percent) {
    this.percent = percent;
  }


  @Override public boolean equals(Coupon coupon) {
    return false;
  }

  @Override public void applyCoupon(List<Product> products) {
    for(Product p : products) {
      if (!p.isCoupon()) {
        double price = p.getPrice() - (p.getPrice() * this.percent) / 100;
        p.setPrice(price);
      }
    }
  }
}

package io.abhi.cartdesign;

import java.util.List;

public class ApplicableOnCateogry extends Coupon {
  private double amount;
  private Cateogry cateogryType;
  private int countOfItem;

  public ApplicableOnCateogry(int id, String name, double amount, Cateogry cateogryType, int countOfItem) {
    super(id, name);
    this.amount = amount;
    this.cateogryType = cateogryType;
    this.countOfItem = countOfItem;
  }

  @Override public boolean equals(Coupon coupon) {
    return false;
  }

  @Override public void applyCoupon(List<Product> products) {
    int cnt = 0;
    for(Product p : products) {
      if (!p.isCoupon()) {
        Item item = (Item) p;
        if (this.getCateogryType().equals(item.getCateogryName())) cnt++;
        if (this.getCountOfItem() == cnt) {
          double price = p.getPrice() - this.amount;
          p.setPrice(price);
          break;
        }
      }
    }

  }

  public double getAmount() {
    return amount;
  }

  public void setAmount(double amount) {
    this.amount = amount;
  }

  public Cateogry getCateogryType() {
    return cateogryType;
  }

  public void setCateogryType(Cateogry cateogryType) {
    this.cateogryType = cateogryType;
  }

  public int getCountOfItem() {
    return countOfItem;
  }

  public void setCountOfItem(int countOfItem) {
    this.countOfItem = countOfItem;
  }

}

package io.abhi.cartdesign;

import java.util.List;

public class ApplicableOnNextItem extends Coupon {
  private double percent;

  public ApplicableOnNextItem(int id, String name, double percent) {
    super(id, name);
    // super();
    this.percent = percent;
  }

  public double getPercent() {
    return percent;
  }

  public void setPercent(double percent) {
    this.percent = percent;
  }

  @Override public boolean equals(Coupon coupon) {
    if (this.getId() == coupon.getId()) return true;
    else return false;
  }

  @Override public void applyCoupon(List<Product> products) {
    boolean found = false;
    for(Product p : products) {
      if (p.isCoupon() && this.equals((Coupon) p)) {
        found = true;
      } else if (found == true && !p.isCoupon()) {
        double price = p.getPrice() - (p.getPrice() * percent) / 100;
        p.setPrice(price);
        break;
      }
    }
  }
}

