package FileAndDirectorySystem;

import java.util.ArrayList;
import java.util.List;

public class Directory extends Entry {
    private List<Entry> entries; // this will contains files and sub directories

    public Directory() {
        this.entries = new ArrayList<>();
    }

    public boolean add(Entry entry) {
        for (Entry e : entries) {
            if (e.getName().equalsIgnoreCase(entry.getName())) {
                return false;
            }
        }
        entries.add(entry);
        return true;
    }

    public boolean delete(String name) {
        boolean result = false;
        for (Entry e : entries) {

            // For directory
            if (e instanceof Directory) {
                result = ((Directory) e).delete(name);
            }

            if (result) {
                return true;
            }

            // for File
            if (e.getName().equalsIgnoreCase(name)) {
                entries.remove(e);
                return true;
            }
        }
        return false;
    }

    public Integer totalSize() {
        int totalSize = 0;
        for (Entry e : entries) {

            // For directory
            if (e instanceof Directory) {
                totalSize += ((Directory) e).totalSize();
            } else {
                totalSize += ((File) e).getSize();
            }
        }
        return totalSize;
    }

    public List<Entry> getEntries() {
        return entries;
    }
}

package FileAndDirectorySystem;

import java.math.BigDecimal;
import java.util.Date;

public abstract class Entry {

    private String name;
    private Date updatedTs;
    private Date lastAccessTs;
    private Date createdTs;
    private Double size;

    public void setName(String name) {
        this.name = name;
    }

    public void setUpdatedTs(Date updatedTs) {
        this.updatedTs = updatedTs;
    }

    public void setLastAccessTs(Date lastAccessTs) {
        this.lastAccessTs = lastAccessTs;
    }

    public void setCreatedTs(Date createdTs) {
        this.createdTs = createdTs;
    }

    public void setSize(Double size) {
        this.size = size;
    }

    public String getName() {
        return name;
    }

    public Date getUpdatedTs() {
        return updatedTs;
    }

    public Date getLastAccessTs() {
        return lastAccessTs;
    }

    public Date getCreatedTs() {
        return createdTs;
    }

    public Double getSize() {
        return size;
    }

    @Override
    public String toString() {
        return "Entry{" +
                "name='" + name + '\'' +
                '}';
    }
}

package FileAndDirectorySystem;

public class File extends Entry {
    private String content;
    private String format;

    public File(String name, Double size, String format) {
        super.setName(name);
        super.setSize(size);
        this.format=format;
    }

    public String getContent() {
        return content;
    }

    public String getFormat() {
        return format;
    }

}

