package FileAndDirectorySystem.search;

import FileAndDirectorySystem.Entry;

import java.util.List;

public class ApplySearchFilter implements SearchCriteria {

    private SearchByFileName searchByFileName;
    private SearchByFormat searchByFormat;
    private SearchBySize searchBySize;

    public ApplySearchFilter() {
        searchByFileName = new SearchByFileName();
        searchByFormat = new SearchByFormat();
        searchBySize = new SearchBySize();
    }

    @Override
    public SearchResponse search(SearchRequest searchRequest, List<Entry> entries) {
        SearchResponse searchResponse = searchByFileName.search(searchRequest, entries);
        searchResponse = searchBySize.search(searchRequest, searchResponse != null ? searchResponse.getResult() : entries);
        searchResponse = searchByFormat.search(searchRequest, searchResponse != null ? searchResponse.getResult() : entries);
        return searchResponse;
    }
}

package FileAndDirectorySystem.search;

import FileAndDirectorySystem.Directory;
import FileAndDirectorySystem.Entry;
import FileAndDirectorySystem.File;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

public class SearchByFileName implements SearchCriteria {

    @Override
    public SearchResponse search(SearchRequest searchRequest , List<Entry> entries) {
        SearchResponse searchResponse = new SearchResponse(new ArrayList<>());
        if(searchRequest.getPattern()==null)
            return searchResponse;

        search(searchRequest.getPattern(), entries, searchResponse);
        return searchResponse;
    }

    public void search(String fileName, List<Entry> entries, SearchResponse searchResponse) {

        for (Entry e : entries) {
            if (e instanceof Directory) {
                for(Entry en : ((Directory) e).getEntries()){
                    if(en instanceof File){
                        if(en.getName().startsWith(fileName)){
                            searchResponse.getResult().add(en);
                        }
                    }
                    else{
                        search(fileName, Collections.singletonList(en), searchResponse);
                    }
                }
            }
            else{
                if(e.getName().equalsIgnoreCase(fileName)){
                    searchResponse.getResult().add(e);
                }
            }
        }
    }
}

package FileAndDirectorySystem.search;

import FileAndDirectorySystem.Directory;
import FileAndDirectorySystem.Entry;
import FileAndDirectorySystem.File;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class SearchByFormat implements SearchCriteria {

    @Override
    public SearchResponse search(SearchRequest searchRequest, List<Entry> entries) {
        SearchResponse searchResponse = new SearchResponse(new ArrayList<>());
        if(searchRequest.getFormat()==null)
            return searchResponse;
        search(searchRequest.getFormat(), entries, searchResponse);
        return searchResponse;
    }

    public void search(String format, List<Entry> entries, SearchResponse searchResponse) {
        for (Entry e : entries) {
            if (e instanceof Directory) {
                for (Entry en : ((Directory) e).getEntries()) {
                    if (en instanceof File) {
                        if (((File) en).getFormat().endsWith(format)) {
                            searchResponse.getResult().add(en);
                        }
                    } else {
                        search(format, Collections.singletonList(en), searchResponse);
                    }
                }
            } else {
                if (((File) e).getFormat().endsWith(format)) {
                    searchResponse.getResult().add(e);
                }
            }
        }
    }
}

package FileAndDirectorySystem.search;

import FileAndDirectorySystem.Directory;
import FileAndDirectorySystem.Entry;
import FileAndDirectorySystem.File;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class SearchBySize implements SearchCriteria {

    @Override
    public SearchResponse search(SearchRequest searchRequest, List<Entry> entries) {
        SearchResponse searchResponse = new SearchResponse(new ArrayList<>());
        if(searchRequest.getMinSize()==null)
            return searchResponse;

        search(searchRequest.getMinSize(), entries, searchResponse);
        return searchResponse;
    }

    public void search(Double minSize, List<Entry> entries, SearchResponse searchResponse) {

        for (Entry e : entries) {
            if (e instanceof Directory) {
                for (Entry en : ((Directory) e).getEntries()) {
                    if (en instanceof File) {
                        if (en.getSize() >= minSize) {
                            searchResponse.getResult().add(en);
                        }
                    } else {
                        search(minSize, Collections.singletonList(en), searchResponse);
                    }
                }
            } else {
                if (e.getSize()>=minSize) {
                    searchResponse.getResult().add(e);
                }
            }
        }
    }
}

