package CTC.Medium;

public class operations {
    int negate(int a) {
        int neg= 0;
        int newSign = a < 0? 1 : -1;
        while (a!= 0) {
            neg+= newSign;
            a += newSign;
        }
        return neg;
        }

    int minus(int a, int b) {
        return a+ negate(b);
    }
    int multiply(int a, int b){
        if(a<b)
            return multiply(a,b);

        int sum=0;
        for(int i = abs(b); i>0; i= minus(i,1)){
            sum+=a;
        }
        if(b<0){
            sum=negate(sum);
        }
        return sum;
    }

    int abs(int b){
        if(b<0)
            return negate(b);

        return b;

    }

    int divide(int a, int b){
        if(b==0)
            throw new java.lang.ArithmeticException();

        int absA=abs(a);
        int absb=abs(b);
        int product =0;
        int x=0;
        while(product+absb<=absA){
            product+=absb;
            x++;
        }

        if((a<0 && b<0)|| (a>0 && b>0))
            return x;
        return negate(x);

    }
    public static void main(String args[]){
        operations o = new operations();
        int a = o.minus(4,2);
        System.out.println("4-2 :" + a);

        int c = o.multiply(5,5);
        System.out.println("5*5 :" + c);

        int d = o.divide(10,2);
        System.out.println("-10/2 :" + d);
    }
}

package DesignDataStructures.HashMap;

public class MyHashMap {
    // for better re-sizing is taken as 2^4
    private static final int SIZE = 16;

    private Entry table[] = new Entry[SIZE];

    /**
     * To store the Map data in key and value pair.
     * Used linked list approach to avoid the collisions
     */
    class Entry {
        final String key;
        String value;
        Entry next;

        Entry(String k, String v) {
            key = k;
            value = v;
        }

        public String getValue() {
            return value;
        }

        public void setValue(String value) {
            this.value = value;
        }

        public String getKey() {
            return key;
        }
    }

    /**
     * Returns the entry mapped to key in the HashMap.
     */
    public Entry get(String k) {
        int hash = k.hashCode() % SIZE;
        Entry e = table[hash];

        // Bucket is identified by hashCode and traversed the bucket
        // till element is not found.
        while(e != null) {
            if(e.key.equals(k)) {
                return e;
            }
            e = e.next;
        }
        return null;
    }

    /**
     * If the map previously contained a mapping for the key, the old
     * value is replaced.
     */
    public void put(String k, String v) {
        int hash = k.hashCode() % SIZE;
        Entry e = table[hash];

        if(e != null) {
            // If we will insert duplicate key-value pair,
            // Old value will be replaced by new one.
            if(e.key.equals(k)) {
                e.value = v;
            } else {
                // Collision: insert new element at the end of list
                // in the same bucket
                while(e.next != null) {
                    e = e.next;
                }
                Entry entryInOldBucket = new Entry(k, v);
                e.next = entryInOldBucket;
            }
        } else {
            // create new bucket for new element in the map.
            Entry entryInNewBucket = new Entry(k, v);
            table[hash] = entryInNewBucket;
        }
    }

    public static void main(String[] args) {
        MyHashMap myHashMap = new MyHashMap();

        myHashMap.put("Awadh", "SSE");
        myHashMap.put("Rahul", "SSE");
        myHashMap.put("Sattu", "SE");
        myHashMap.put("Gaurav", "SE");

        Entry e = myHashMap.get("Awadh");
        System.out.println(""+e.getValue());
    }
}

