public class reverseFirstK {

    public static void main(String [] args){
        Queue<Integer> q = new LinkedList<>();
        q.add(4);
        q.add(3);
        q.add(1);
        q.add(10);
        q.add(2);
        q.add(6);

        q = reverse(q,2);
        int a = q.size();
        for(int i=0; i< a;i++){
            System.out.print(q.poll()+" ");
        }
    }

    private static Queue<Integer> reverse(Queue<Integer> q, int k) {
        Stack<Integer> st = new Stack<>();
        while(k>0){
            st.push(q.poll());
            k--;
        }
        Queue<Integer> q2 = new LinkedList<>();
        while(!st.isEmpty())
            q2.add(st.pop());

        while(!q.isEmpty())
            q2.add(q.poll());

        return q2;

    }
}

package SlidingWindow;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;

public class SlidingWindowMax {

    public static void main(String [] args){
        int[] res = new int[]{1,3,-1,-3,5,3,6,7};
        int k=3;
        int[] res2 = maxSlidingWindow(res,k);


    }

    public static int[] maxSlidingWindow(int[] a, int k) {
        if (a == null || k <= 0) {
            return new int[0];
        }
        int n = a.length;
        int[] r = new int[n-k+1];
        int ri = 0;
        // store index
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < a.length; i++) {
            // remove numbers out of range k
            while (!q.isEmpty() && q.peek() < i - k + 1) {
                q.poll();
            }
            // remove smaller numbers in k range as they are useless
            while (!q.isEmpty() && a[q.peekLast()] < a[i]) {
                q.pollLast();
            }
            // q contains index... r contains content
            q.offer(i);
            if (i >= k - 1) {
                r[ri++] = a[q.peek()];
            }
        }
        return r;
    }
}

package sorting;

import java.util.*;

public class DistantBarcodes {
    public static void main(String args[]){
        int[] arr = new int [] {1,1,1,2,2,2};

        arr = rearrangeBarcodes(arr);
        //System.out.println(Arrays.toString(ls.toArray()));
    }

    public static int[] rearrangeBarcodes(int[] barcodes) {
        HashMap<Integer,Integer> hm = new HashMap<>();

        if(barcodes == null || barcodes.length == 0)
            return new int[0];

        for(int a: barcodes)
            hm.put(a,hm.getOrDefault(a,0)+1);

        PriorityQueue<Map.Entry<Integer, Integer>> pq = new PriorityQueue<Map.Entry<Integer, Integer>>(
                (a,b)->b.getValue()-a.getValue() == 0?a.getKey() - b.getKey(): b.getValue() - a.getValue());

        for(Map.Entry<Integer,Integer> mentry : hm.entrySet())
            pq.offer(mentry);

        int i=0;
        while(!pq.isEmpty()){
            int k=2;
            List<Map.Entry> ls = new ArrayList<Map.Entry>();
            while(k>0 && !pq.isEmpty()){
                Map.Entry<Integer,Integer> mentry1= pq.poll();
                barcodes[i++]=mentry1.getKey();
                mentry1.setValue(mentry1.getValue()-1);
                ls.add(mentry1);
                k--;
            }
            for(Map.Entry<Integer,Integer> e:ls){
                if(e.getValue()>0)
                    pq.add(e);
            }
            if(pq.isEmpty())
                break;
        }
        return barcodes;
    }
}

package sorting;

import java.util.*;

public class largestNumber {

    private static class LargestNumberComporator implements Comparator<String>{
        @Override
        public int compare(String a, String b){
            String order1 = a+b;
            String order2 = b+a;
            return order2.compareTo(order1);
        }
    }

    public static void main(String args[]) {
        int[] arr = new int[]{3,30,34,5,9};
        String word = largestNumber(arr);
        System.out.println(word);
    }

    public static String largestNumber(int[] nums) {
        String []str = new String[nums.length];
        int i=0;
        for(int a: nums){
            str[i++]=String.valueOf(a);
        }

        Arrays.sort(str,new LargestNumberComporator());

        if (str[0].equals("0")) {
            return "0";
        }

        // Build largest number from sorted array.
        String largestNumberStr = new String();
        for (String numAsStr : str) {
            largestNumberStr += numAsStr;
        }

        return largestNumberStr;

    }
}

