public class ExpenseManager {
    List<Expense> expenses;
    public Map<String, User> userMap;
    Map<String, Map<String, Double>> balanceSheet;

    public ExpenseManager() {
        expenses= new ArrayList<Expense>();
        userMap= new HashMap<String, User>();
        balanceSheet= new HashMap<String, Map<String, Double>>();
    }

    public void addUser(User user){
        userMap.put(user.getId(),user);
        balanceSheet.put(user.getId(),new HashMap<String, Double>());
    }

    public void addExpense(ExpenseType expenseType, double amount, String paidBy, List<Split> splits){
        Expense expense= ExpenseService.createExpense(expenseType,amount,userMap.get(paidBy),splits);
        expenses.add(expense);

        for(Split split: splits){
            String paidTo= split.getUser().getId();
            Map<String, Double> balances= balanceSheet.get(paidBy);

            //updating balanceSheet of paidBy
            if(!balances.containsKey(paidTo))
                balances.put(paidTo,0.0);

            balances.put(paidTo,balances.get(paidTo) + split.getAmount());

            //updating balanceSheet of paidTo
            balances= balanceSheet.get(paidTo);

            if(!balances.containsKey(paidBy))
                balances.put(paidBy,0.0);

            balances.put(paidBy, balances.get(paidBy) - split.getAmount());
        }
    }

    public void showExpense(String userId){
        boolean isEmpty= true;

        for(Map.Entry<String, Double> userBalance: balanceSheet.get(userId).entrySet()){
            if(userBalance.getValue() != 0){
                isEmpty=false;
                printBalance(userId, userBalance.getKey(), userBalance.getValue());
            }
        }

        if(isEmpty){
            System.out.println("No Balances");
        }
    }

    private void printBalance(String user1, String user2, double amount) {
        String user1Name = userMap.get(user1).getName();
        String user2Name = userMap.get(user2).getName();
        if (amount < 0) {
            System.out.println(user1Name + " owes " + user2Name + ": " + Math.abs(amount));
        } else if (amount > 0) {
            System.out.println(user2Name + " owes " + user1Name + ": " + Math.abs(amount));
        }
    }

    public void showBalances(){
        boolean isEmpty= true;

        for(Map.Entry<String, Map<String, Double>> allBalances: balanceSheet.entrySet() ){
            for(Map.Entry<String, Double> userBalance: allBalances.getValue().entrySet()){
                if(userBalance.getValue() > 0){
                    isEmpty= false;
                    printBalance(allBalances.getKey(),userBalance.getKey(),userBalance.getValue());
                }
            }
        }

        if(isEmpty){
            System.out.println("No Balances");
        }
    }
}

package service;

import model.Expense.EqualExpense;
import model.Expense.ExactExpense;
import model.Expense.Expense;
import model.Expense.PercentExpense;
import model.ExpenseType;
import model.Split.PercentSplit;
import model.Split.Split;
import model.User;

import java.util.List;

public class ExpenseService {
    public static Expense createExpense(ExpenseType expenseType, double amount, User paidBy, List<Split> splits){
        switch (expenseType){
            case EXACT:
                return new ExactExpense(amount, paidBy, splits);
            case EQUAL:
                int totalSplitSize= splits.size();
                double splitAmount= (double) Math.round(amount*100/totalSplitSize)/100.0;
                for(Split split: splits){
                    split.setAmount(splitAmount);
                }

                splits.get(0).setAmount(splitAmount + amount - splitAmount*totalSplitSize);
                return new EqualExpense(amount, paidBy, splits);
            case PERCENT:
                for(Split split: splits){
                    PercentSplit percentSplit= (PercentSplit) split;
                    split.setAmount((amount * percentSplit.getPercent())/100.0);
                }
                return new PercentExpense(amount, paidBy, splits);
        }

        return null;
    }
}

