        if (end.getCurrentPiece()!=null && end.getCurrentPiece().getColor() == this.getColor()) {
            return false;
        }
        return true;
    }

    public boolean isCastlingMove() {
        return castlingMove;
    }

    public void setCastlingMove(boolean castlingMove) {
        this.castlingMove = castlingMove;
    }
}

