package cache.policies;

import algorithms.DoublyLinkedList;
import algorithms.DoublyLinkedListNode;

import java.util.HashMap;
import java.util.Map;

public class LRUEvictionPolicy<Key> implements EvictionPolicy<Key>{

    private DoublyLinkedList<Key> dll;
    private Map<Key, DoublyLinkedListNode<Key>> mapper;

    public LRUEvictionPolicy(){
        this.dll = new DoublyLinkedList<>();
        this.mapper = new HashMap<>();
    }

    @Override
    public void keyAccessed(Key key) {

     if(mapper.containsKey(key)){

         dll.detachNode(mapper.get(key));
         dll.addElementAtLast(key);
     }else{
         DoublyLinkedListNode<Key> newNode = dll.addElementAtLast(key);
         mapper.put(key, newNode);
     }

    }

    @Override
    public Key evictKey() {
        DoublyLinkedListNode<Key> node = dll.getLastNode();

        if(node!= null){
            dll.detachNode(node);
            return node.getElement();
        }
        return null;
    }
}

package cache.storage;

import cache.exceptions.NotFoundException;
import cache.exceptions.StorageFullException;

import java.util.HashMap;
import java.util.Map;

public class HashMapBasedStorage<Key,Value> implements Storage<Key,Value>{

    Map<Key,Value> storage;
    private final Integer capacity;

    public  HashMapBasedStorage(Integer capacity){
        this.capacity = capacity;
        storage = new HashMap<>();
    }

    @Override
    public void add(Key key, Value value) throws StorageFullException {
      if(isStorageFull()) throw new StorageFullException("Capacity full....");
          storage.put(key,value);
    }

    @Override
    public void remove(Key key)throws NotFoundException {

       if(!storage.containsKey(key)) throw new NotFoundException(key +" doesn't exist in cache.");
       storage.remove(key);
    }

    @Override
    public Value get(Key key) throws NotFoundException {
        if(!storage.containsKey(key)) throw new NotFoundException(key +" doesn't exist in cache.");
        return storage.get(key);
    }

    private boolean isStorageFull(){
        return capacity == storage.size();
    }

}

