	}
	
	public ArrayList<String> findErrorMoreThantwoChild(ArrayList<Integer>Ind,ArrayList<String>ErrorRes) throws NullPointerException, ArrayIndexOutOfBoundsException
	{
		
		for(int i=0;i<256;i++) 
		{
			if(Ind.get(i)>2) 
