	}
	
	
	public ArrayList<String> Cycledetector(ArrayList<String>ErrorRes,int[][]adjArray) throws NullPointerException, ArrayIndexOutOfBoundsException 
	{
	
		int []visited=new int[256];
		int []stack=new int[256];
		int found=0;
		CycleDetector cycleDetectorObj = new CycleDetector();
		for(int i=0;i<256;i++) {
			if(adjArray[0][i]!=0)
		found=cycleDetectorObj.dfs(i,adjArray,visited,stack);
		if(found==1) {ErrorRes.add(E3); break;}
		}
		return ErrorRes;
	}
	
	
	public ArrayList<String> MultipleRootDetector(ArrayList<Integer>Indeg, ArrayList<String>ErrorRes, ArrayList<Integer>Out) throws NullPointerException, ArrayIndexOutOfBoundsException 
	{
		int count=0;
		for(int i=0;i<Out.size();i++) 
		{
			//System.out.print("In:out"+i+"("+Indeg.get(i)+":"+Out.get(i)+")"+"\t");
			if(Out.get(i)>0 && Indeg.get(i)==0) 
