package com.mlc.models;

import java.util.Deque;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Iterator;

public abstract class LRUCache {
    Deque<String> dq;
    HashSet<String> map;
    int capacity;

    public LRUCache(int n) {
        dq = new LinkedList<>();
        map = new HashSet<>();
        capacity = n;
    }

    public boolean read(String val) {
        if(!map.contains(val)) {
            return false;
        } else {
            int index = 0, i=0;
            Iterator<String> itr = dq.iterator();
            while(itr.hasNext()) {
                if(itr.next() == val) {
                    index = i;
                    break;
                }
                i++;
            }
            dq.remove(index);
            dq.push(val);
            return true;
        }
    }

    public boolean write(String val) {
        boolean returnVal = false;
        if(!map.contains(val)) {
            if(dq.size() == capacity) {
                String last = dq.removeLast();
                map.remove(last);
            }
            returnVal = true;
        } else {
            int index = 0, i=0;
            Iterator<String> itr = dq.iterator();
            while(itr.hasNext()) {
                if(itr.next() == val) {
                    index = i;
                    break;
                }
                i++;
            }
            dq.remove(index);
        }
        dq.push(val);
        map.add(val);
        return returnVal;
    }

    public int getCapacity() {
        return capacity;
    }

    public int getFilledSize() {
        int filledSize = map.size();
        return filledSize;
    }
}

package com.mlc.services;

import com.mlc.models.*;

import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Iterator;
import java.util.ArrayList;
import java.util.List;

public class MultiLevelCache {
    PriorityQueue<Cache> pq;

    public MultiLevelCache(int numLayers) {
        this.pq = new PriorityQueue<Cache>(numLayers, new CacheComparator());
    }

    public void addLayer(String capacity, String readTime, String writeTime, int priority) {
        int cap = Integer.parseInt(capacity);
        int rt = Integer.parseInt(readTime);
        int wt = Integer.parseInt(writeTime);

        pq.add(new Cache(cap, rt, wt, priority));
    }

    public int write(String val) {
        Iterator itr = pq.iterator();
        int totalWriteTime = 0;
        while(itr.hasNext()) {
            Cache curLevelCache = (Cache) (itr.next());
            boolean didWrite = curLevelCache.write(val);
            if(didWrite) {
                totalWriteTime += curLevelCache.getWriteTime();
            }
        }
        return totalWriteTime;
    }

    public int read(String val) {
        Iterator itr = pq.iterator();
        int totalReadTime = 0;
        int readTillIndex = -1;
        boolean foundElement = false;
        Cache curLevelCache;
        while(itr.hasNext() && !foundElement) {
            curLevelCache = (Cache) (itr.next());
            foundElement = curLevelCache.read(val);
            totalReadTime += curLevelCache.getReadTime();
            readTillIndex++;
        }
        itr = pq.iterator();
        int curWriteIndex = 0;
        while(itr.hasNext() && curWriteIndex < readTillIndex) {
            curLevelCache = (Cache) (itr.next());
            boolean didWrite = curLevelCache.write(val);
            if(didWrite) {
                totalReadTime += curLevelCache.getWriteTime();
            }
        }
        return totalReadTime;
    }

    public List<Integer> getCacheSize() {
        List<Integer> cacheSizes = new ArrayList<Integer>();
        Iterator itr = pq.iterator();
        while(itr.hasNext()) {
            Cache curLevelCache = (Cache) (itr.next());
            cacheSizes.add(curLevelCache.getFilledSize());
        }
        return cacheSizes;
    }
}

class CacheComparator implements Comparator<Cache> {
    public int compare(Cache c1, Cache c2) {
        if(c1.getPriority() < c2.getPriority()) {
            return 1;
        } else if(c1.getPriority() > c2.getPriority()) {
            return -1;
        }
        return 0;
    }
}

package com.mlc.view;

import com.mlc.services.MultiLevelCache;

import java.util.Scanner;
import java.util.List;

public class MainView {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int numLayers = Integer.parseInt(scanner.nextLine());

        String capacityLine = scanner.nextLine();
        String[] capacities = capacityLine.split(" ");

        String readTimeLine = scanner.nextLine();
        String[] readTimes = readTimeLine.split(" ");

        String writeTimeLine = scanner.nextLine();
        String[] writeTimes = writeTimeLine.split(" ");

        MultiLevelCache mlcache = new MultiLevelCache(numLayers);
        for(int i=0; i<numLayers; i++) {
            //numLayers-i gives first added element the highest priority and so on
            mlcache.addLayer(capacities[i], readTimes[i], writeTimes[i], i+1);
        }

        while(true) {
            String command = scanner.nextLine();
            String[] commands = command.split(" ");
            String commandType = commands[0];
            switch(commandType) {
                case "WRITE":
                    System.out.println("Write Time is: " + mlcache.write(commands[1]));
                    break;
                case "READ":
                    System.out.println("Read Time is: " + mlcache.read(commands[1]));
                    break;
                case "CACHESIZE":
                    System.out.println("Cache Size for Each Layer is: ");
                    List<Integer> cacheSizes = mlcache.getCacheSize();
                    for(int i=0; i<cacheSizes.size(); i++) {
                        System.out.println("Layer " + (i+1) + ": " + cacheSizes.get(i));
                    }
                    break;
            }
        }

    }
}

