public class MessagingQueue {
    Node front , rear;
    int size, capacity;
    MessagingQueue(int capacity){
        this.front = null;
        this.rear = null;
        this.capacity=capacity;
        this.size=0;
    }

    boolean isEmpty(){
        return (size==0);
    }

    boolean isFull(){
        return (size==capacity);
    }

    Message getFront(){
        return (isEmpty())?null: this.front.message;
    }

    boolean addMessage(Message msg){
        if(isFull()){
            return false;
        }
        Node temp = new Node(msg);
        if(front==null){
            front = temp;
        }else{
            rear.next=temp;
        }
        size++;
        rear=temp;
        return true;
    }

    boolean removeMessage(){
        if(isEmpty()){
            return false;
        }
        Node temp = this.front;
        if(front== rear){
            front = null;
            rear = null;
        }else{
            front = front.next;
        }
        size--;
        return true;
    }

    void setSize(int size){
        if(size>capacity)
            this.capacity = size;
    }
}

public class Node {
    Message message;
    Node next;

    public Node(Message m){
        message = m;
        next=null;
    }
}

public interface Publisher {
    boolean addToMessageQueue(Message message);
}

public class PublisherImpl implements Publisher{
    PubSubCommonService pubSubCommonService;

    public PublisherImpl(PubSubCommonService pubSubCommonService){
        this.pubSubCommonService = pubSubCommonService;
    }

    @Override
    public boolean addToMessageQueue(Message message){
        int retries = 3, count=0;
        boolean isSuccess=false;
        while(count<retries && !isSuccess){
            isSuccess = pubSubCommonService.addToMessageQueue(message);
            count++;
        }
        return isSuccess;
    }
}

public interface PubSubCommonService {
    boolean addToMessageQueue(Message message);
    void addSubscriber(String regex, Consumer consumer);
    void removeSubscriber(String regex, Consumer consumer);
    void downloadMessages(Consumer consumer);
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class PubSubCommonServiceImpl implements PubSubCommonService {
    Map<Consumer, MessagingQueue> messagingQueueMap;
    Map<String, Set<Consumer>> suscribersMap;
    int queueSize;

    public PubSubCommonServiceImpl(int size){
        messagingQueueMap = new HashMap<>();
        suscribersMap = new HashMap<>();
        queueSize = size;
    }

    @Override
    public boolean addToMessageQueue(Message message) {
        boolean isSuccess =true;
        if(isSuccess){
            String regex = message.getRegex();
            if(suscribersMap.containsKey(regex)){
                Set<Consumer> consumers = suscribersMap.get(regex);
                for(Consumer consumer : consumers){
                    isSuccess = consumer.addMessageToList(message);
                    if(!isSuccess){
                        addMessageToConsumerQueue(message, consumer);
                    }
                }
            }
        }
        return isSuccess;
    }

    private void addMessageToConsumerQueue(Message message, Consumer consumer) {
        MessagingQueue messagingQueue = null;
        if(messagingQueueMap.containsKey(consumer)){
            messagingQueue = messagingQueueMap.get(consumer);
            messagingQueue.addMessage(message);
            messagingQueueMap.put(consumer, messagingQueue);
        }else{
            messagingQueue = new MessagingQueue(queueSize);
            messagingQueue.addMessage(message);
            messagingQueueMap.put(consumer, messagingQueue);
        }
    }

    @Override
    public void addSubscriber(String regex, Consumer consumer) {
        Set<Consumer> consumers = null;
        if(suscribersMap.containsKey(regex)){
            consumers = suscribersMap.get(regex);
            consumers.add(consumer);
            suscribersMap.put(regex, consumers);
        }else{
            consumers = new HashSet<>();
            consumers.add(consumer);
            suscribersMap.put(regex, consumers);
        }
    }

    @Override
    public void removeSubscriber(String regex, Consumer consumer) {
        if(suscribersMap.containsKey(regex)){
            Set<Consumer> consumers = suscribersMap.get(regex);
            consumers.remove(consumer);
            suscribersMap.put(regex, consumers);
        }
    }

    @Override
    public void downloadMessages(Consumer consumer) {
        if(messagingQueueMap.containsKey(consumer)){
            System.out.println("Downloading messages for consumer with name="+consumer.getName());
            MessagingQueue messagingQueue = messagingQueueMap.get(consumer);
            while(!messagingQueue.isEmpty()){
                Message message = messagingQueue.getFront();
                System.out.println("New message is "+message.payload);
                consumer.addMessageToList(message);
                messagingQueue.removeMessage();
            }
        }
    }

}

package RateLimiter;

import java.time.Duration;
import java.time.Instant;
import java.util.LinkedList;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class RedisService {

    private int rateLimitPerMinute;

    public RedisService(int rpm) {
        rateLimitPerMinute = rpm;
    }

    // User name to request mapping for storing requests for each user
    private Map<String, LinkedList<Request>> userIdToRequest = new ConcurrentHashMap<>();

    public boolean addNewUser(String userName, Instant requestedTs) {
        LinkedList<Request> requests = new LinkedList<>();
        requests.add(new Request(requestedTs, 1));
        userIdToRequest.put(userName, requests);
        System.out.println("New User !!! - " + userName);
        return true;
    }

    public synchronized boolean requestHit(String userName, Instant ts) {

        if (!userIdToRequest.containsKey(userName)) {
            return addNewUser(userName, ts);
        } else {
            if (getTotalElapsedRequest(userName) < rateLimitPerMinute) {
                LinkedList<Request> tmp = userIdToRequest.get(userName);
                tmp.add(new Request(ts, 1));
                userIdToRequest.put(userName, tmp);
                return true;
            } else {
                boolean actionTaken = false;
                for (int i = 0; i < userIdToRequest.get(userName).size(); i++) {
                    Duration duration = Duration.between(userIdToRequest.get(userName).get(i).getTs(), ts);
                    if (duration.getSeconds() >= 60) {
                        userIdToRequest.get(userName).remove(i);
                        actionTaken = true;
                    } else {
                        break;
                    }
                }

                // case 1 - if some entries are older than 1 minute evict those and insert new entry
                // and return true
                if (actionTaken) {
                    LinkedList<Request> tmp = userIdToRequest.get(userName);
                    tmp.add(new Request(ts, 1));
                    userIdToRequest.put(userName, tmp);
                    return true;
                }

                // case 2 - if all entries are within 1 minute,
                // then rate has been breached and return false
                return false;
            }
        }
    }

    private int getTotalElapsedRequest(String userName) {
        return userIdToRequest.get(userName).stream().mapToInt(Request::getCount).sum();
    }
}

class Request {
    private Instant ts;
    private int count;

    public Request(Instant ts, int count) {
        this.ts = ts;
        this.count = count;
    }

    public Instant getTs() {
        return ts;
    }

    public int getCount() {
        return count;
    }
}

package RateLimiter;

import java.time.Instant;

public class SimpleThread extends Thread {

    private RedisService redisService;

    public SimpleThread(String str, RedisService rs) {
        super(str);
        this.redisService = rs;
    }

    public void run() {
        for (int i = 1; i <= 70; i++) {
            System.out.println("Thread Name - " + getName() + " Time - " + i + " " + hit(getName(), Instant.now()));
            try {
                sleep(1000);
            } catch (InterruptedException e) {
            }
        }
        System.out.println("DONE! " + getName());
    }


    private boolean hit(String userName, Instant ts) {
        return redisService.requestHit(userName, ts);
    }
}

