import java.util.HashMap;
import java.util.Map;

/**
 * @author rajesh.c on 09/12/18.
 */
public class DirectionCalculator
{
    public static final Map<String, Direction> bearingToDirection = new HashMap<String, Direction>() {{
        put("N", Direction.STRAIGHT);
        put("NNE", Direction.SLIGHT_RIGHT);
        put("NE", Direction.SLIGHT_RIGHT);
        put("ENE", Direction.RIGHT);
        put("E", Direction.RIGHT);
        put("N", Direction.STRAIGHT);
        put("NNW", Direction.SLIGHT_LEFT);
        put("NW", Direction.SLIGHT_LEFT);
        put("WNW", Direction.LEFT);
        put("W", Direction.LEFT);
        put("WSW", Direction.EXTREME_LEFT);
        put("SW", Direction.EXTREME_LEFT);
        put("SSW", Direction.EXTREME_LEFT);
        put("S", Direction.U_TURN);
        put("ESE", Direction.EXTREME_RIGHT);
        put("SE", Direction.EXTREME_RIGHT);
        put("SSE", Direction.EXTREME_RIGHT);
    }};

    public static String getBearing(double lat1, double lon1, double lat2, double lon2)
    {
        double latitude1 = Math.toRadians(lat1);
        double latitude2 = Math.toRadians(lat2);
        double longDiff = Math.toRadians(lon2 - lon1);
        double y = Math.sin(longDiff) * Math.cos(latitude2);
        double x =
                Math.cos(latitude1) * Math.sin(latitude2) - Math.sin(latitude1) * Math.cos(latitude2) * Math.cos(
                        longDiff);

        double resultDegree = (Math.toDegrees(Math.atan2(y, x)) + 360) % 360;

        String[] coordNames = {"N", "NNE", "NE", "ENE", "E",
                "ESE", "SE", "SSE", "S", "SSW", "SW",
                "WSW", "W", "WNW", "NW", "NNW", "N"};

        double directionid = Math.round(resultDegree / 22.5);
        if (directionid < 0)
        {
            directionid = directionid + 16;
        }

        String compasLoc = coordNames[(int) directionid];
        return compasLoc;
    }
}

/**
 * @author rajesh.c on 09/12/18.
 */
public class DistanceCalculator
{
    public static double getDistance(double lat1, double lon1, double lat2, double lon2, char unit)
    {
        double theta = lon1 - lon2;
        double dist =
                Math.sin(deg2rad(lat1)) * Math.sin(deg2rad(lat2)) + Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) * Math
                        .cos(deg2rad(theta));
        dist = Math.acos(dist);
        dist = rad2deg(dist);
        dist = dist * 60 * 1.1515;
        if (unit == 'K')
        {
            dist = dist * 1.609344;
        }
        else if (unit == 'N')
        {
            dist = dist * 0.8684;
        }
        return (dist);
    }

    private static double deg2rad(double deg)
    {
        return (deg * Math.PI / 180.0);
    }

    private static double rad2deg(double rad)
    {
        return (rad * 180.0 / Math.PI);
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Main
{
    public static void main(String[] args)
    {
        double speed = 10;
        String csvFile = "directions.txt";
        String cvsSplitBy = ",";

        List<Point> gpsPoints = getGpsPoints(csvFile, cvsSplitBy);
        int time = 0;

        for (int i = 0; i < gpsPoints.size() - 1; i++)
        {
            Point currentPoint = gpsPoints.get(i);
            Point nextPoint = gpsPoints.get(i + 1);
            double distance = DistanceCalculator.getDistance(currentPoint.getLatitude(),
                                                             currentPoint.getLongitude(),
                                                             nextPoint.getLatitude(),
                                                             nextPoint.getLongitude(),
                                                             'K');
            String bearing = DirectionCalculator.getBearing(currentPoint.getLatitude(),
                                                            currentPoint.getLongitude(),
                                                            nextPoint.getLatitude(),
                                                            nextPoint.getLongitude());

            Direction direction = DirectionCalculator.bearingToDirection.get(bearing);

            if (i == 0)
            {
                System.out.println("Time = " + time + " Start");
            }

            if (direction != Direction.STRAIGHT && i != 0)
            {
                System.out.println("Time = " + time + " Take " + direction.name());
            }

            System.out.println("Time = " + time + " Go straight for " + distance + " kms");
            time += distance / speed;
        }
    }

    private static List<Point> getGpsPoints(final String csvFile, final String cvsSplitBy)
    {
        List<Point> gpsPoints = new ArrayList<>();
        String line = "";
        try (BufferedReader br = new BufferedReader(new FileReader(csvFile)))
        {
            while ((line = br.readLine()) != null)
            {
                String[] pointInformation = line.split(cvsSplitBy);
                gpsPoints.add(new Point(Double.parseDouble(pointInformation[0]),
                                        Double.parseDouble(pointInformation[1])));
            }
        }
        catch (IOException e)
        {
            e.printStackTrace();
        }
        return gpsPoints;
    }
}

