        while(!stk.isEmpty()){
            for(int val : rooms.get(stk.pop())){
                if(roomsVisited[val]==0){
                    roomsVisited[val]++;
                    stk.push(val);
                }
            }
        }

        for(int i=1;i<rooms.size();i++){
            if(roomsVisited[i]==0) return false;
        }
        return true;
    }
}

package LeetCode;

import java.util.*;

public class SkyLineProblem {
    public List<List<Integer>> getSkyline(int[][] buildings) {
        List<List<Integer>> result = new ArrayList<>();
        List<int[]> height = new ArrayList<>();
        for (int[] b : buildings) {
            height.add(new int[]{b[0], -b[2]});
            height.add(new int[]{b[1], b[2]});
        }
        Collections.sort(height, (a, b) -> {
            if (a[0] != b[0])
                return a[0] - b[0];
            return a[1] - b[1];
        });
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> (b - a));
        pq.offer(0);
        int prev = 0;
        for (int[] h : height) {
            if (h[1] < 0) {
                pq.offer(-h[1]);
            } else {
                pq.remove(h[1]);
            }
            int cur = pq.peek();
            if (prev != cur) {
                List<Integer> tmp = new ArrayList<>();
                tmp.add(h[0]);
                tmp.add(cur);
                result.add(new ArrayList<>(tmp));
                prev = cur;
            }
        }
        return result;
    }
}

package LeetCode;

public class SlidingWindowMaximum {
    public int[] maxSlidingWindow(int[] nums, int k) {

        int[] left = new int[nums.length];
        int[] right= new int[nums.length];
        int[] result = new int[nums.length-k+1];
        left[0] = nums[0];
        right[nums.length-1] = nums[nums.length-1];
        for(int i=1;i<nums.length;i++){
            left[i] = (i%k==0)?nums[i]:Math.max(left[i-1],nums[i]);

            right[nums.length-1-i]=((nums.length-1-i) %k==0)?nums[nums.length-1-i]:Math.max(right[nums.length-1-i+1],nums[nums.length-1-i]);
        }

        for(int i=0;i<nums.length-k+1;i++){
            result[i]=Math.max(right[i],left[i+k-1]);
        }
        return result;
    }
}

package LeetCode;

public class Sort012inPlace {
    public void sortColors(int[] nums) {

        int lo=0,mid=0, hi = nums.length-1;

        while(mid<=hi){
            if(nums[mid]==0){
                int tmp = nums[lo];
                nums[lo] = nums[mid];
                nums[mid] = tmp;
                lo++; mid++;
            }else if(nums[mid]==1) mid++;
            else{
                int tmp = nums[hi];
                nums[hi]= nums[mid];
                nums[mid]=tmp;
                hi--;
            }

        }

    }
}

package LeetCode;

import java.util.ArrayList;
import java.util.List;

public class SplitArrayToFibonnaci {
    public List<Integer> splitIntoFibonacci(String S) {
        List<Integer> result = new ArrayList<>();
        helper(S,result,0);
        return result;
    }

    private boolean helper(String s, List<Integer> result,int pos){
        if(pos == s.length()) {
            return result.size() > 2;
        }

        int num=0;
        int n = s.length();
        for(int i=pos;i<n;i++){
            num= (num*10) + (s.charAt(i)-'0');
            if(num<0) return false;
            if(result.size()<2 || (result.get(result.size()-1) + result.get(result.size()-2))==num){
                result.add(num);
                if(helper(s,result,i+1)) return true;
                result.remove(result.size()-1);
            }
            if(i==pos && s.charAt(i)=='0') return false;
        }
        return false;
    }
}

package LeetCode;

public class SquareOfSortedArray {
    public int[] sortedSquares(int[] A) {

        int positive=0;
        while(positive<A.length && A[positive]<0) positive++;

        int negative = positive-1;
        int i=0;
        int[] result = new int[A.length];
        while(negative>= 0 && positive<A.length){
            if(A[negative]*A[negative] > A[positive]*A[positive]){
                result[i++]=A[positive]*A[positive];
                positive++;
            }else {
                result[i++]=A[negative]*A[negative];
                negative--;
            }
        }

        while(negative>=0){
            result[i++]=A[negative]*A[negative];
            negative--;
        }

        while(positive<A.length){
            result[i++]=A[positive]*A[positive];
            positive++;
        }

        return result;
    }
}

package LeetCode;

public class SymmetricTree {
    public boolean isSymmetric(TreeNode root) {
        if(root==null) return true;
        if(checkMirror(root.left,root.right)) return true;
        return false;
    }

    private boolean checkMirror(TreeNode node1, TreeNode node2){
        if(node1==null && node2 ==null) return true;
        if(node1 ==null || node2==null) return false;

        return (node1.val==node2.val)&&checkMirror(node1.left,node2.right)&&checkMirror(node1.right,node2.left);
    }
}

package LeetCode;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ThreeSum {
    public List<List<Integer>> threeSum(int[] nums, int targetValue) {
        List<List<Integer>> result = new ArrayList<>() ;
        Arrays.sort(nums);
        for(int i=0;i<nums.length-2;i++) {

            if(i>0 && nums[i] == nums[i-1]) continue;
            int target = targetValue-nums[i];
            int low = i+1, high = nums.length-1;

            while(low<high){

                if(nums[low]+nums[high]== target){
                    result.add(Arrays.asList(nums[low],nums[high],nums[i]));
                    while(low<high && nums[low]==nums[low+1]) low++;
                    while(low<high && nums[high]==nums[high-1]) high--;
                    low++;
                    high--;
                }else if(nums[low]+nums[high]<target) low++;
                else high--;
            }

        }

        return result;
    }
}

package LeetCode;

import java.util.Arrays;

public class ThreeSumClosest {
    public int threeSumClosest(int[] nums, int target) {
        Arrays.sort(nums);
        int sum= nums[0]+nums[1]+nums[nums.length-1];

        for(int i=0;i<nums.length-2;i++){
            int lo=i+1, hi=nums.length-1;
            int tmp=0;

            while(lo<hi){
                tmp=nums[i]+nums[lo]+nums[hi];
                if(tmp>target) hi--;
                else lo++;

                if(Math.abs(sum-target)>Math.abs(tmp-target)){
                    sum=tmp;
                }
            }
        }
        return sum;
    }
}

