	    if(turn == USER) {
		System.out.println("Your move");
		move = -1;
		while (move<0 || move>9 || board[move/3][move%3] != EMPTY) {
		    System.out.println("Please enter your move(0-8): ");
                    Scanner in = new Scanner(System.in);
                    
		    move = in.nextInt();
		   // Console.in.readChar();
		}
	    } else {
		move = computer_move(board);
		System.out.println("Computer move: " + move);
	    }

	    // Update the board
	    board[(int)(move/3)][move%3] = turn;

	    // Print the board
	    print_board(board);

	    // if game is over
	    winner = checkWinner(board);

	    if(winner != NONE)
		break;

	    // switch turn
	    if(turn == USER) {
		turn = COMPUTER;
	    } else {
		turn = USER;
	    }

	}

	// Print out the outcome
	switch(winner) {
	case USER:
	    System.out.println("You won!");
	    break;
	case COMPUTER: 
	    System.out.println("Computer won!");
	    break;
	default:
	    System.out.println("Tie!");
	    break;
	}
    
    }
    
    // Print the board
    public static void print_board(int[][] board) {
	System.out.print(printChar(board[0][0]));
	System.out.print("|");
	System.out.print(printChar(board[0][1]));
	System.out.print("|");
	System.out.println(printChar(board[0][2]));
	System.out.println("-----");
	System.out.print(printChar(board[1][0]));
	System.out.print("|");
	System.out.print(printChar(board[1][1]));
	System.out.print("|");
	System.out.println(printChar(board[1][2]));
	System.out.println("-----");
	System.out.print(printChar(board[2][0]));
	System.out.print("|");
	System.out.print(printChar(board[2][1]));
	System.out.print("|");
	System.out.println(printChar(board[2][2]));
    }

    // Return an X or O, depending upon whose move it was
    public static char printChar(int b) {
	switch(b) {
	case EMPTY:
	    return ' ';
	case USER:
	    return 'X';
	case COMPUTER:
	    return 'O';
	}
	return ' ';
    }

    // See if the game is over
    public static int checkWinner(int[][] board) {
	// Check if someone won
	// Check horizontals

	// top row
	if((board[0][0] == board[0][1]) && (board[0][1] == board[0][2]))
	    return board[0][0];

	// middle row
	if((board[1][0] == board[1][1]) && (board[1][1] == board[1][2]))
	    return board[1][0];

	// bottom row
	if((board[2][0] == board[2][1]) && (board[2][1] == board[2][2]))
	    return board[2][0];

	// Check verticals

	// left column
	if((board[0][0] == board[1][0]) && (board[1][0] == board[2][0]))
	    return board[0][0];

	// middle column
	if((board[0][1] == board[1][1]) && (board[1][1] == board[2][1]))
	    return board[0][1];

	// right column
	if((board[0][2] == board[1][2]) && (board[1][2] == board[2][2]))
	    return board[0][2];

	// Check diagonals
	// one diagonal
	if((board[0][0] == board[1][1]) && (board[1][1] == board[2][2]))
	    return board[0][0];

	// the other diagonal
	if((board[0][2] == board[1][1]) && (board[1][1] == board[2][0]))
	    return board[0][2];

	// Check if the board is full
	if(board[0][0] == EMPTY || 
           board[0][1] == EMPTY || 
           board[0][2] == EMPTY || 
	   board[1][0] == EMPTY ||
	   board[1][1] == EMPTY ||
	   board[1][2] == EMPTY ||
	   board[2][0] == EMPTY ||
	   board[2][1] == EMPTY ||
	   board[2][2] == EMPTY)
	    return NONE;

	return STALEMATE;
    }

    // Generate a random computer move
    public static int computer_move(int[][] board) {
	int move = (int)(Math.random()*9);

	while(board[move/3][move%3] != EMPTY) 
	    move = (int)(Math.random()*9);

	return move;
    }


}

package UrlShortern;

/**
 *
 * @author nikhil.agrawal
 */
public class TinyUrlShortern {

    public static final int base = 66;

     public static void main(String[] args) {
        int n = 200;
        String shortendUrl=idToShortUrl(n);
//        String shortendUrl2="geeksforgeeks";

        System.out.println("shortend url :: " + shortendUrl);
        System.out.println("Integer id from shortend url :: " + shortUrltoID(shortendUrl));

    }

     public static String idToShortUrl(int n)
     {
         // Converting base 10 to base 62 
         String s = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789?#!.";
         char map[]= s.toCharArray();
         String shortUrl="";
//         System.out.println("Before processing :: " + n);

         while(n>=0)
         {

             if(shortUrl.isEmpty())
             {
                shortUrl +=  map[n%base]; 
             }
             else
             {
                 shortUrl= map[n%base] + shortUrl;
             }
//              System.out.println("n before = " + n + " shorturl = " + shortUrl);
             n=n/base;
//             System.out.println("n after = " + n+ " shorturl = " + shortUrl);
             if(n==0)
              break;
         }
         return shortUrl;
//         return new StringBuilder(shortUrl).reverse().toString();
     }

     public static int shortUrltoID(String shortUrl)
     {

         if(shortUrl==null || shortUrl.isEmpty()) 
             return -1;

         char[] shorturl = shortUrl.toCharArray();

         int id=0;

         for(char c : shorturl)
         {
             if(c>='a' && c<='z')
             {
                 id=(id*base) + c-'a';
             }
             else if(c>='A' && c<='Z')
             {
                 id=(id*base) + c-'A' +26;
             }
             else if(c>='0' && c<='9')
             {
                 id=(id*base) + c-'0' +52;
             }
             else if(c>'9')
             {
                 id=(id*base) + c-'?' +62;
             }
         }
         return id;


     }





}

