/**
 * @author priyamvora
 * @created 29/05/2021
 */
public class ScheduledExecutorQueue {
    private final PriorityQueue<ScheduledTask> scheduledTasks;
    private final Thread[] workerThreads;

    public ScheduledExecutorQueue(int poolSize) {
        this.scheduledTasks = new PriorityQueue<>();
        workerThreads = new Thread[poolSize];
        intializeWorkerThreads();
    }

    private void intializeWorkerThreads() {
        for (int i = 0; i < workerThreads.length; i++) {
            workerThreads[i] = new Thread(() -> {
                try {
                    polling();
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            });

            workerThreads[i].start();
        }
    }

    public void addScheduledTask(ScheduledTask task) {
        synchronized (scheduledTasks) {
            System.out.println("Add task to queue: " + task);
            scheduledTasks.add(task);
            scheduledTasks.notifyAll();
        }
    }

    private void polling() throws InterruptedException {
        while (true) {
            ScheduledTask taskToExecute = null;
            System.out.println("Thread: " + Thread.currentThread().getId() + " trying to acquire lock");
            synchronized (scheduledTasks) {
                System.out.println("Thread: " + Thread.currentThread().getId() + " acquired lock");
                while (scheduledTasks.isEmpty()) {
                    System.out.println("Thread: " + Thread.currentThread().getId() + " waiting");
                    scheduledTasks.wait();
                }
                ScheduledTask task = scheduledTasks.peek();
                if (task.getScheduledExecutionTime() <= System.currentTimeMillis()) {
                    taskToExecute = scheduledTasks.poll();
                }
                //scheduledTasks.notifyAll();
            }
            if (taskToExecute == null) {
                //   System.out.println("Thread: " + Thread.currentThread().getId() + " going to sleep");
                Thread.sleep(2000);
                continue;
            }
            // For fixed rate add at initialDelay + period, initialDelay + 2*period
            if (taskToExecute != null && taskToExecute.getScheduledTaskType().equals(ScheduledTaskType.FIXED_RATE)) {
                ScheduledTask scheduledTask = cloneScheduledTask(taskToExecute);
                scheduledTask.setScheduledExecutionTime(System.currentTimeMillis() + scheduledTask.getSchedulePeriodInMillis());
                addScheduledTask(scheduledTask);
            }
            System.out.println("Thread: " + Thread.currentThread().getId() + " executing a task");
            taskToExecute.getTask().run();
            // For fixed delay add at currentEndTime + period;
            if (taskToExecute != null && taskToExecute.getScheduledTaskType().equals(ScheduledTaskType.FIXED_DELAY)) {
                ScheduledTask scheduledTask = cloneScheduledTask(taskToExecute);
                scheduledTask.setScheduledExecutionTime(System.currentTimeMillis() + scheduledTask.getSchedulePeriodInMillis());
                addScheduledTask(scheduledTask);
            }
        }

    }

    private ScheduledTask cloneScheduledTask(ScheduledTask scheduledTask) {
        ScheduledTask clone = new ScheduledTask(scheduledTask.getTask(), scheduledTask.getScheduledExecutionTime(), scheduledTask.getScheduledTaskType(), scheduledTask.getSchedulePeriodInMillis());
        return clone;
    }
}

package customThreadPoolExecutor;

import customThreadPoolExecutor.constants.ScheduledTaskType;
import customThreadPoolExecutor.model.ScheduledTask;

import java.util.concurrent.TimeUnit;

/**
 * @author priyamvora
 * @created 29/05/2021
 */
public class ScheduledExecutorService {
    private final ScheduledExecutorQueue scheduledExecutorQueue;

    public ScheduledExecutorService(int poolSize) {
        this.scheduledExecutorQueue = new ScheduledExecutorQueue(poolSize);
    }

    /**
     * Creates and executes a one-shot action that becomes enabled after the given delay.
     */
    public void schedule(Runnable command, long delay, TimeUnit unit) {
        Long currentTimeMillis = System.currentTimeMillis();
        Long delayInMillis = unit.toMillis(delay);
        scheduledExecutorQueue.addScheduledTask(new ScheduledTask(command, currentTimeMillis + delayInMillis, ScheduledTaskType.ONE_SHOT));
    }

    /**
     * Creates and executes a periodic action that becomes enabled first after the given initial delay, and
     * subsequently with the given period; that is executions will commence after initialDelay then
     * initialDelay+period, then initialDelay + 2 * period, and so on.
     */
    public void scheduleAtFixedRate(Runnable command, long initialDelay, long period, TimeUnit unit) {
        Long currentTimeMillis = System.currentTimeMillis();
        Long delayInMillis = unit.toMillis(initialDelay);
        scheduledExecutorQueue.addScheduledTask(new ScheduledTask(command, currentTimeMillis + delayInMillis, ScheduledTaskType.FIXED_RATE, unit.toMillis(period)));
    }

    /*
     * Creates and executes a periodic action that becomes enabled first after the given initial delay, and
     * subsequently with the given delay between the termination of one execution and the commencement of the next.
     */
    public void scheduleWithFixedDelay(Runnable command, long initialDelay, long delay, TimeUnit unit) {
        Long currentTimeMillis = System.currentTimeMillis();
        Long delayInMillis = unit.toMillis(initialDelay);
        scheduledExecutorQueue.addScheduledTask(new ScheduledTask(command, currentTimeMillis + delayInMillis, ScheduledTaskType.FIXED_DELAY, unit.toMillis(delay)));
    }
}

package elevator;

import java.util.LinkedList;
import java.util.Queue;

/**
 * @author priyamvora
 * @created 19/04/2021
 */
public class FCFS {
    private final Queue<Integer> passengerRequests;
    private Integer currentFloor;
    private final Integer maxFloors;

    public FCFS(Integer maxFloors) {
        passengerRequests = new LinkedList<>();
        currentFloor = 0;
        this.maxFloors = maxFloors;
    }

    public Integer servePassengers() {
        Integer totalCosts = 0;
        while (!passengerRequests.isEmpty()) {
            Integer floorToReach = passengerRequests.poll();
            totalCosts += Math.abs(currentFloor - floorToReach);
            currentFloor = floorToReach;
        }
        return totalCosts;
    }

    public void addPassengerRequest(Integer floorNumber) {
        passengerRequests.add(floorNumber);
    }
}

package elevator;

import java.util.TreeSet;

/**
 * @author priyamvora
 * @created 20/04/2021
 */
public class LOOK {
    private final TreeSet<Integer> passengerRequests;
    private Integer currentFloor;
    private Integer direction;
    private final Integer maxFloors;
    private final Integer minFloors;

    public LOOK() {
        this.passengerRequests = new TreeSet<>();
        this.currentFloor = 0;
        this.direction = 1;
        this.maxFloors = 100;
        this.minFloors = 0;
    }

    public void servePassengerRequests() {
        while (true) {
            Integer nextFloorAccToDirection;
            if (direction == 1) {
                nextFloorAccToDirection = passengerRequests.ceiling(currentFloor);
            } else {
                nextFloorAccToDirection = passengerRequests.floor(currentFloor);
            }
            if (nextFloorAccToDirection == null) {
                direction = 1 - direction;
            } else {
                currentFloor = nextFloorAccToDirection;
                passengerRequests.remove(currentFloor);
            }
        }
    }

    public void addPassenger(Integer floor) {
        passengerRequests.add(floor);
    }
}

package elevator;

import java.util.TreeSet;

/**
 * @author priyamvora
 * @created 20/04/2021
 */
public class SCAN {
    private final TreeSet<Integer> passengerRequests;
    private Integer currentFloor;
    private Integer currentDirection;
    private final Integer MAX_FLOORS = 100;
    private final Integer MIN_FLOORS = 0;

    public SCAN() {
        this.passengerRequests = new TreeSet<>();
        this.currentFloor = 0;
        this.currentDirection = 1;
    }

    public void servePassengerRequests() {
        while (true) {
            if (currentDirection == 1) {
                Integer nextFloor = passengerRequests.ceiling(currentFloor);
                if (nextFloor == null) {
                    currentFloor++;
                } else {
                    currentFloor = nextFloor;
                    passengerRequests.remove(nextFloor);
                }
            } else {
                Integer nextFloor = passengerRequests.floor(currentFloor);
                if (nextFloor == null) {
                    currentFloor--;
                } else {
                    currentFloor = nextFloor;
                    passengerRequests.remove(nextFloor);
                }
            }
            if (currentFloor.equals(MAX_FLOORS) || currentFloor.equals(MIN_FLOORS)) {
                currentDirection = 1 - currentDirection;
            }
        }
    }

    public void addPassengerRequest(Integer floor) {
        passengerRequests.add(floor);
    }
}

package elevator;

import java.util.PriorityQueue;
import java.util.TreeSet;

/**
 * @author priyamvora
 * @created 20/04/2021
 */
public class SSTF {
    private final TreeSet<Integer> passengerRequests;
    private Integer currentFloor;

    public SSTF() {
        passengerRequests = new TreeSet<>();
        currentFloor = 0;
    }

    public Integer servePassengers() {
        Integer totalTime = 0;
        while (true) {
            if (passengerRequests.isEmpty()) {
                return totalTime;
            }
            Integer greaterThanCurrentFloor = passengerRequests.ceiling(currentFloor);
            Integer lowerThanCurrentFloor = passengerRequests.floor(currentFloor);
            if (greaterThanCurrentFloor == null && lowerThanCurrentFloor != null) {
                totalTime += currentFloor - lowerThanCurrentFloor;
                currentFloor = lowerThanCurrentFloor;
            } else if (greaterThanCurrentFloor != null && lowerThanCurrentFloor == null) {
                totalTime += greaterThanCurrentFloor - currentFloor;
                currentFloor = greaterThanCurrentFloor;
            } else if (Math.abs(greaterThanCurrentFloor - currentFloor) < Math.abs(lowerThanCurrentFloor - currentFloor)) {
                totalTime += greaterThanCurrentFloor - currentFloor;
                currentFloor = greaterThanCurrentFloor;
            } else {
                totalTime += currentFloor - lowerThanCurrentFloor;
                currentFloor = lowerThanCurrentFloor;
            }
            passengerRequests.remove(currentFloor);
        }
    }

    public void addPassengerRequests(Integer passengerRequest) {
        passengerRequests.add(passengerRequest);
    }
}

