package multiThreadedMessageQueue.handler;

import multiThreadedMessageQueue.model.Message;
import multiThreadedMessageQueue.model.Topic;
import multiThreadedMessageQueue.model.TopicSubscriber;

/**
 * @author priyamvora
 * @created 29/05/2021
 */
public class SubscriberWorker implements Runnable {
    private final Topic topic;
    private final TopicSubscriber topicSubscriber;

    public SubscriberWorker(Topic topic, TopicSubscriber topicSubscriber) {
        this.topic = topic;
        this.topicSubscriber = topicSubscriber;
    }

    @Override
    public void run() {
        synchronized (topicSubscriber) {
            do {
                Integer currentOffset = topicSubscriber.getOffset().get();
                System.out.println("ThreadID - " + Thread.currentThread().getId() + " Subscriber: " + topicSubscriber.getSubscriber().getId() + " offset now: " + currentOffset);
                while (currentOffset >= topic.getMessageList().size()) {
                    try {
                        System.out.println("Subscriber: " + topicSubscriber.getSubscriber().getId() + " Waiting for message");
                        topicSubscriber.wait();
                    } catch (InterruptedException e) {
                        e.printStackTrace();
                    }
                }
                Message message = topic.getMessageList().get(currentOffset);
                try {
                    topicSubscriber.getSubscriber().consume(message);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }

                topicSubscriber.getOffset().compareAndSet(currentOffset, currentOffset + 1);
            } while (true);
        }
    }

    public void wakeUpIfNeeded() {
        synchronized (topicSubscriber) {
            topicSubscriber.notify();
        }
    }
}

package multiThreadedMessageQueue.handler;

import multiThreadedMessageQueue.model.Topic;
import multiThreadedMessageQueue.model.TopicSubscriber;

import java.util.HashMap;
import java.util.Map;

/**
 * @author priyamvora
 * @created 29/05/2021
 */
public class TopicHandler {
    private final Topic topic;
    private final Map<String, SubscriberWorker> subscriberWorkerMap;

    public TopicHandler(Topic topic) {
        this.topic = topic;
        this.subscriberWorkerMap = new HashMap<>();
    }

    public void publish() {
        for (TopicSubscriber topicSubscriber : topic.getTopicSubscribers()) {
            startSubscriberWorker(topicSubscriber);
        }
    }

    public void startSubscriberWorker(TopicSubscriber topicSubscriber) {
        if (!subscriberWorkerMap.containsKey(topicSubscriber.getSubscriber().getId())) {
            SubscriberWorker subscriberWorker = new SubscriberWorker(topic, topicSubscriber);
            subscriberWorkerMap.put(topicSubscriber.getSubscriber().getId(), subscriberWorker);
            new Thread(subscriberWorker).start();
        }
        SubscriberWorker subscriberWorker = subscriberWorkerMap.get(topicSubscriber.getSubscriber().getId());
        subscriberWorker.wakeUpIfNeeded();

    }
}

